/bin/bash -lc "cat > cases.ml <<'EOF'
open Decision

let x = S O
let y = S x
let z = S y
let field name t tail = Typ_rcd_cons (name, t, tail)
let record a b = field a Typ_nat (field b Typ_top Typ_rcd_nil)
let bind name t tail = Cons (Pair (name, Bind_sub t), tail)
let rec_self = Typ_mu (Typ_bvar O)
let test name expected e a b =
  if decidability a b e <> expected then failwith name
  else Printf.printf \"ok %s\\n\" name

let () =
  test \"nat reflexivity\" Left Nil Typ_nat Typ_nat;
  test \"top is not below nat\" Right Nil Typ_top Typ_nat;
  test \"unbound variable below top\" Right Nil (Typ_fvar x) Typ_top;
  test \"promoting through two bounds\" Left
    (bind y (Typ_fvar x) (bind x Typ_nat Nil)) (Typ_fvar y) Typ_nat;
  test \"duplicate binding keys\" Right (bind x Typ_nat (bind x Typ_nat Nil)) Typ_nat Typ_nat;
  test \"term binding cannot promote\" Right (Cons (Pair (x, Bind_typ Typ_nat), Nil))
    (Typ_fvar x) Typ_nat;
  test \"contravariant argument\" Left Nil
    (Typ_arrow (Typ_top, Typ_nat)) (Typ_arrow (Typ_nat, Typ_top));
  test \"recursive reflexivity\" Left Nil rec_self rec_self;
  test \"recursive mismatch\" Right Nil rec_self (Typ_mu Typ_nat);
  test \"ill-scoped recursive type\" Right Nil (Typ_mu (Typ_bvar (S O))) Typ_top;
  test \"nested recursive and universal binders\" Left Nil
    (Typ_mu (Typ_all (Typ_bvar O, Typ_bvar (S O))))
    (Typ_mu (Typ_all (Typ_bvar O, Typ_bvar (S O))));
  test \"record width\" Left Nil (record x y) (field x Typ_top Typ_rcd_nil);
  test \"missing field\" Right Nil (record x y) (field z Typ_top Typ_rcd_nil);
  test \"duplicate field\" Right Nil (record x x) Typ_top;
  test \"equivalent reordered universal bounds\" Left Nil
    (Typ_all (record x y, Typ_bvar O))
    (Typ_all (field y Typ_top (field x Typ_nat Typ_rcd_nil), Typ_bvar O));
  test \"inequivalent universal bounds\" Right Nil
    (Typ_all (record x y, Typ_bvar O))
    (Typ_all (field x Typ_nat Typ_rcd_nil, Typ_bvar O))
EOF
ocamlc -w -a -o cases decision.mli decision.ml cases.ml && ./cases"

